// Synthetic public receiving IO fixtures; no network, credentials, clinical or operational data.
import fs from'node:fs';import vm from'node:vm';import assert from'node:assert/strict';import{webcrypto}from'node:crypto';import{material,oracle,wire,seal,ref,publication,path as framePath,clone}from'./serving_protocol_v1_cases.mjs';
export const K=1024,M=K*K,SITES='https://kennedyjasondavid-eng.github.io/conc-kitchen-house/sites.json',POINTER='https://kennedyjasondavid-eng.github.io/conc-kitchen-door/protocol-v1/publication.json',BASE='https://kennedyjasondavid-eng.github.io/conc-kitchen-door/',SECRET='PRIVATE_PUBLIC_IO_ERROR_CANARY';
export const bytes=s=>new TextEncoder().encode(s),plain=v=>JSON.parse(JSON.stringify(v)),eventLoop=()=>new Promise(r=>setImmediate(r));
export const sites={_meta:{schemaVersion:1,owner:'conc-kitchen-house'},sites:[{key:'rexdale',numbersProtocol:'door-serving-v1',numbersFrom:'conc-kitchen-door/protocol-v1/publication.json'}]};
export function fixture(sequence=1,text=null){const m=material();if(text)m.rotation[0].menu.regular=text;const p=oracle(m),flow={...p.flowBase,publication:publication(sequence)},frame={schema:1,protocol:m.protocol,site:m.site,generationRef:ref(p.publicInputWitness),flow,material:m},body=wire(frame),pointer={schema:1,protocol:m.protocol,site:m.site,generationRef:clone(frame.generationRef),flow:clone(flow),frame:{path:framePath(sequence),sha256:seal(body)}};return{pointer,frame,body,url:BASE+framePath(sequence)}}
export function core(crypto=webcrypto){const source=fs.readFileSync(process.env.SERVING_PUBLIC_IO_HTML||process.env.SERVING_PROTOCOL_HTML||new URL('../../index.html',import.meta.url),'utf8');let src='';for(const region of['flow-validity','serving-protocol-v1','serving-public-io-v1']){const a=source.indexOf('/* HOUSE_TESTABLE_CORE_START '+region+' */'),z=source.indexOf('/* HOUSE_TESTABLE_CORE_END '+region+' */',a);assert.ok(a>=0&&z>a,'actual portable '+region+' source exists');src+=source.slice(a,z)+'\n'}const ambient=[],no=()=>{ambient.push(true);throw Error(SECRET)};const c=vm.createContext({crypto,TextEncoder,TextDecoder,Uint8Array,URL,Headers,ReadableStream,fetch:no,AbortController:class{constructor(){no()}},setTimeout:no,clearTimeout:no,console:{log:no,warn:no,error:no},localStorage:{getItem:no,setItem:no}});vm.runInContext(src,c);assert.equal(typeof c.houseServingV1PublicIOCreate,'function');return{c,ambient}}
export function clock(){let n=0;const active=new Map(),scheduled=[],cleared=[];return{active,scheduled,cleared,setTimeout(fn,ms){const id=++n;active.set(id,fn);scheduled.push({id,fn,ms});return id},clearTimeout(id){cleared.push(id);active.delete(id)},fire(){for(const[id,fn]of[...active]){active.delete(id);fn()}}}}
export function response(url,chunks,{status=200,type='cors',redirected=false,headers={},neverRead=false,readError=false,cancelStalls=false}={}){const stats={read:0,get:0,cancel:0,release:0,bulk:0,reasons:[]};let i=0;const body={getReader(){stats.get++;return{read(){stats.read++;if(neverRead)return new Promise(()=>{});if(readError)return Promise.reject(Error(SECRET));return Promise.resolve(i<chunks.length?{done:false,value:chunks[i++]}:{done:true})},cancel(reason){stats.cancel++;stats.reasons.push(reason);return cancelStalls?new Promise(()=>{}):Promise.resolve()},releaseLock(){stats.release++}}},cancel(reason){stats.cancel++;stats.reasons.push(reason);return cancelStalls?new Promise(()=>{}):Promise.resolve()}};const bulk=()=>{stats.bulk++;throw Error(SECRET)};return{value:{status,type,redirected,url,headers:new Headers(headers),body,text:bulk,json:bulk,arrayBuffer:bulk},stats}}
export function setup(fetcher,crypto){const{c,ambient}=core(crypto),timers=clock(),calls=[],controllers=[];class Controller extends AbortController{constructor(){super();controllers.push(this)}}const caps={fetch:(url,init)=>{calls.push({url,init});return fetcher(url,init,calls.length)},AbortController:Controller,setTimeout:timers.setTimeout.bind(timers),clearTimeout:timers.clearTimeout.bind(timers)};const made=c.houseServingV1PublicIOCreate({site:'rexdale'},caps);assert.equal(made.ok,true);assert.deepEqual(Object.keys(made.io).sort(),['fetchReleased','fetchSites']);return{...made,c,caps,ambient,timers,calls,controllers}}
export function good(f=fixture(),second=f.pointer){const wires=[];return{wires,fetcher:async(url,init,n)=>{const w=response(url,[url===POINTER?wire(n===1?f.pointer:second):url===SITES?wire(sites):f.body]);wires.push(w);return w.value}}}
export function frameFailure(r,reason){assert.equal(r.kind,'frame');assert.equal(r.validation.ok,false);if(reason)assert.equal(r.validation.reason,reason);assert.ok(!JSON.stringify(r).includes(SECRET));return r.validation}
export function noObservation(r){assert.equal(Object.hasOwn(r.validation,'observation'),false)}
export{clone,wire,seal};
